RADIX = 255
OFF1, OFF2, INTOFF, LITSIZE = 5, 2, 9, 4


class Coder:
    """Exact mirror of decomp.c arithmetic decoder, in encode direction."""
    def __init__(self):
        self.cc = {}
        self.low = 0
        self.range = 1
        self.n = 0
        self.cost = 0.0
        self.stats = {}

    def bit(self, ctx, b):
        if self.range < RADIX:
            self.range *= RADIX
            self.low *= RADIX
            self.n += 1
        c = self.cc.get(ctx)
        if c is None:
            c = [0, 0]
            self.cc[ctx] = c
        split = (self.range * (c[0] + 1)) // (c[0] + c[1] + 2)
        if b:
            if split >= self.range:
                raise RuntimeError('impossible bit 1 ctx=%d' % ctx)
            self.low += split
            newr = self.range - split
        else:
            if split <= 0:
                raise RuntimeError('impossible bit 0 ctx=%d' % ctx)
            newr = split
        self.cost += -math.log2(newr / self.range)
        s = self.stats.get(ctx)
        if s is None:
            s = [0.0, 0, 0.0, 0]
            self.stats[ctx] = s
        s[2 * b] += -math.log2(newr / self.range)
        s[2 * b + 1] += 1
        self.range = newr
        c[b] += 1

    def integer(self, t0, ctx, v):
        assert v >= 0
        result = v + (1 << t0)
        m = result.bit_length() - 1
        k = m - t0 + 1
        c99 = ctx * 99
        for j in range(1, k):
            self.bit(c99 + t0 + j, 0)
        self.bit(c99 + t0 + k, 1)
        for j in range(m - 1, -1, -1):
            self.bit(c99, (result >> j) & 1)

    def finish(self):
        low, rng, n = self.low, self.range, self.n
        best = None
        for k in range(n, -1, -1):
            p = pow(RADIX, k)
            q = -((-(low + 1)) // p)  # ceil((low+1)/p) == P+1
            V = q * p - 1
            if low <= V < low + rng and V >= 0:
                best = (V, n - k)
                break
        if best is None:
            best = (low, n)
        V, ndig = best
        digits = []
        x = V
        for _ in range(n):
            digits.append(x % RADIX)
            x //= RADIX
        digits.reverse()
        digits = digits[:ndig]
        return bytes(d + 1 for d in digits)


