    coder.integer(INTOFF, 0, len(tokens))
    for t in tokens:
        if t[0] == 'l':
            coder.bit(1, 0)
            s, v = lit_bits(t[1])
            coder.bit(8, s)
            coder.integer(LITSIZE, 9, v)
        else:
            _, off, ln = t
            coder.bit(1, 1)
            coder.integer(OFF1, 2, off)
            coder.integer(OFF2, 3, ln - 1)


