class CostModel:
    def __init__(self, stats=None):
        self.c = {}
        if stats:
            for ctx, s in stats.items():
                c0 = s[0] / s[1] if s[1] else None
                c1 = s[2] / s[3] if s[3] else None
                if c0 is None:
                    c0 = 8.0
                if c1 is None:
                    c1 = 8.0
                self.c[ctx] = (c0, c1)

    def bit(self, ctx, b):
        e = self.c.get(ctx)
        if e is None:
            return 1.0
        return e[b]

    def integer(self, t0, ctx, v):
        result = v + (1 << t0)
        m = result.bit_length() - 1
        k = m - t0 + 1
        c99 = ctx * 99
        tot = 0.0
        for j in range(1, k):
            tot += self.bit(c99 + t0 + j, 0)
        tot += self.bit(c99 + t0 + k, 1)
        for j in range(m - 1, -1, -1):
            tot += self.bit(c99, (result >> j) & 1)
        return tot

